[CmdletBinding()]
param([string]$ProjectRoot=(Get-Location).Path,[string]$ManifestPath='',[switch]$RequireManifest,[switch]$SkipPathExistence)
$ErrorActionPreference='Stop'; if ($ManifestPath -or $SkipPathExistence) { throw 'ManifestPath and SkipPathExistence are unsupported in strict validation. Use ProjectRoot with .spec/manifest.yaml.' }; . (Join-Path $PSScriptRoot 'python-runtime.ps1'); $python = Get-TengerPython; if(-not $RequireManifest){Write-Warning 'Manifest validation always requires .spec/manifest.yaml in the current executable governance contract.'}; & $python (Join-Path $PSScriptRoot 'validate_core.py') artifact --project-root $ProjectRoot; exit $LASTEXITCODE
